function subdivide({x1: xA, y1: yA, x2: xB, y2: yB, x3: xC, y3: yC, contains: contains}) {
	let dAB = distSquared(xA, yA, xB, yB);
  let dBC = distSquared(xB, yB, xC, yC);
  let dCA = distSquared(xC, yC, xA, yA);
	let triangle1, triangle2;
	var t = random(0.25, 0.75);
	if (dAB > dBC && dAB > dCA) {
    let [xD, yD] = lerpPoints(xA, yA, xB, yB, t);
		triangle1 = {x1: xA, y1: yA, x2: xC, y2: yC, x3: xD, y3: yD, contains: []};
		triangle2 = {x1: xB, y1: yB, x2: xC, y2: yC, x3: xD, y3: yD, contains: []};
  } else if (dBC > dAB && dBC > dCA) {
    let [xD, yD] = lerpPoints(xB, yB, xC, yC, t);
		triangle1 = {x1: xB, y1: yB, x2: xA, y2: yA, x3: xD, y3: yD, contains: []};
		triangle2 = {x1: xC, y1: yC, x2: xA, y2: yA, x3: xD, y3: yD, contains: []};
  } else {
    let [xD, yD] = lerpPoints(xC, yC, xA, yA, t);
		triangle1 = {x1: xC, y1: yC, x2: xB, y2: yB, x3: xD, y3: yD, contains: []};
		triangle2 = {x1: xA, y1: yA, x2: xB, y2: yB, x3: xD, y3: yD, contains: []};
  }

	for (let idx of contains) {
		if (pointInTriangle(points[idx], triangle1)) triangle1.contains.push(idx);
		else if (pointInTriangle(points[idx], triangle2)) triangle2.contains.push(idx);
	}

	if (triangle1.contains.length > 1) subdivide(triangle1);
	else triangle(triangle1.x1, triangle1.y1, triangle1.x2, triangle1.y2, triangle1.x3, triangle1.y3);
	if (triangle2.contains.length > 1) subdivide(triangle2);
	else triangle(triangle2.x1, triangle2.y1, triangle2.x2, triangle2.y2, triangle2.x3, triangle2.y3);
}

function distSquared(x1, y1, x2, y2) {
  return mag(x2-x1, y2-y1);
}

function lerpPoints(x1, y1, x2, y2, t) {
  let x3 = (1-t)*x1 + t*x2;
  let y3 = (1-t)*y1 + t*y2;
  return [x3, y3];
}

function pointInTriangle({x: px, y: py}, {x1: xA, y1: yA, x2: xB, y2: yB, x3: xC, y3: yC}) {
	let A = triangleArea(xA, yA, xB, yB, xC, yC);
	let A1 = triangleArea(px, py, xB, yB, xC, yC);
	let A2 = triangleArea(xA, yA, px, py, xC, yC); 
	let A3 = triangleArea(xA, yA, xB, yB, px, py);

	return (abs(A1+A2+A3 - A) < 0.01);
}

function triangleArea(x1, y1, x2, y2, x3, y3) {
	return abs((x1*(y2-y3) + x2*(y3-y1)+ x3*(y1-y2))/2); 
}
